  caral: { n: 'Civilização Caral-Supe', p: 'Caral, Peru', d: 'A cidade mais antiga conhecida das Américas floresce na costa peruana com pirâmides monumentais — sem cerâmica, sem vestígios de guerra, e com registros semelhantes aos quipus.' },
  akkad: { n: 'Império Acádio — o primeiro império', p: 'Acade, Mesopotâmia', d: 'Sargão da Acádia forja o primeiro império multiétnico da história, estendendo-se do golfo Pérsico ao Mediterrâneo.' },
