  hammurabi: { n: 'Código de Hamurábi', p: 'Babilônia', d: 'Hamurábi promulga um dos códigos jurídicos decifrados mais antigos: 282 leis gravadas numa estela de pedra — “olho por olho”.' },
  bronze_collapse: { n: 'Colapso da Idade do Bronze Final', p: 'Mediterrâneo Oriental', d: 'Em poucas décadas, as economias palacianas de Micenas a Ugarit colapsam — seca, fome, terremotos e os enigmáticos “Povos do Mar”.' },
  troy: { n: 'Guerra de Troia (data tradicional)', p: 'Troia, Anatólia', d: 'Lenda e arqueologia se confundem: uma guerra por Helena de Troia, depois imortalizada por Homero, por volta da época em que o mundo do Bronze se desfazia.' },
  phoenician_alpha: { n: 'Alfabeto fenício', p: 'Biblos, Fenícia', d: 'Comerciantes fenícios criam um alfabeto consonantal de 22 letras — o ancestral do grego, do latim, do árabe, do hebraico e da maioria das escritas em uso hoje.' },
