  olmec: { n: 'Civilização olmeca', p: 'La Venta, México', d: 'A “cultura-mãe” da Mesoamérica esculpe cabeças colossais de pedra e estabelece padrões rituais que povos maias e astecas herdarão mais tarde.' },
  zhou: { n: 'Dinastia Zhou', p: 'Haojing, China', d: 'A dinastia mais longa da China introduz o “Mandato do Céu”, enquanto seus séculos finais produzem Confúcio, Laozi e as Cem Escolas de Pensamento.' },
