  homer: { n: 'Homero compõe a Ilíada e a Odisseia', p: 'Jônia (Esmirna)', d: 'Bardo cego ou tradição de bardos — de qualquer forma, a pedra fundamental da literatura ocidental é lançada na costa da Ásia Menor.' },
  scythia: { n: 'Reino cita', p: 'Estepe do baixo Dnipro, Ucrânia', d: 'Nômades a cavalo, entrevistados por Heródoto, dominam a estepe ucraniana e comercializam grãos com Atenas; seus kurgans reais ainda revelam obras-primas de ouro como o Pectoral.' },
  buddha: { n: 'Siddhartha Gautama — o Buda', p: 'Bodh Gaya, Índia', d: 'Um príncipe do clã Shakya atinge a iluminação sob a árvore Bodhi e ensina o Caminho do Meio, fundando uma das grandes religiões do mundo.' },
  confucius: { n: 'Confúcio', p: 'Qufu, China', d: 'O pensador mais influente da China ensina uma ética de lealdade familiar, ritual e governo benevolente — suas ideias moldam o Leste Asiático até hoje.' },
