  temple_destroyed: { n: 'Nabucodonosor destrói Jerusalém', p: 'Jerusalém', d: 'Exércitos babilônicos incendeiam o Templo de Salomão e deportam a elite de Judá para a Babilônia — o cativeiro babilônico.' },
