  bosporan: { n: 'Reino do Bósforo', p: 'Panticapeu (Kerch)', d: 'Um reino de governantes gregos, abrangendo as duas margens do estreito de Kerch, torna-se o cliente mais oriental de Roma — e o grande condutor do comércio entre a Estepe e o Mar Negro.' },
  warring_states: { n: 'Período dos Reinos Combatentes', p: 'China', d: 'Sete reinos chineses travam uma guerra de aniquilação de 250 anos, impulsionando uma corrida armamentista de filosofia, tática e tecnologia — da qual emergem os Qin.' },
