  kierkegaard: { n: 'Søren Kierkegaard', p: 'Copenhague', d: 'Dinamarquês melancólico, mestre da ironia e pai do existencialismo: “A vida só pode ser compreendida olhando para trás; mas deve ser vivida para a frente.”' },
  latin_independence: { n: 'Independência da América Latina', p: 'América espanhola', d: 'Do México à Argentina, a América espanhola liberta-se em quinze anos de guerra.' },
