  greek_independence: { n: 'Guerra de Independência da Grécia', p: 'Grécia', d: 'Após 400 anos, a Grécia liberta-se do domínio otomano — Byron morre em Missolonghi e o filo-helenismo varre a Europa.' },
  manifesto: { n: 'O Manifesto Comunista', p: 'Londres', d: 'Marx e Engels publicam no revolucionário ano de 1848: “Um espectro ronda a Europa.”' },
