  darwin: { n: 'Charles Darwin', p: 'Londres', d: 'Cinco anos no Beagle, vinte anos de cautela — então A Origem das Espécies (1859) vira de cabeça para baixo a história da vida.' },
  origin_species: { n: 'A Origem das Espécies', p: 'Londres', d: 'Evolução por seleção natural — a biologia torna-se ciência, e a sociedade discute isso até hoje.' },
  civil_war: { n: 'Guerra Civil Americana', p: 'Estados Unidos', d: 'A guerra mais letal dos EUA: mais de 600.000 mortos; Gettysburg, Antietam, a Marcha de Sherman — e a escravidão abolida.' },
  lincoln: { n: 'Abraham Lincoln', p: 'Illinois, EUA', d: 'Salvou a União, libertou os escravizados, “sem malícia contra ninguém” — baleado no teatro cinco dias após a vitória.' },
  shevchenko: { n: 'Taras Shevchenko', p: 'Kaniv, Ucrânia', d: 'Comprado da servidão por uma loteria sobre um retrato de Briullov, tornou-se o poeta nacional: o Kobzar (1840) provou que a língua ucraniana viva servia à grande literatura. Por pertencer a uma irmandade secreta foi recrutado à força e exilado por dez anos, proibido de escrever; está enterrado nas colinas do Dnipro, sobre Kaniv.' },
  meiji: { n: 'Restauração Meiji', p: 'Tóquio', d: 'Termina o governo dos samurais; o Japão industrializa-se em velocidade relâmpago — do isolamento feudal à potência mundial em uma geração.' },
  german_unification: { n: 'Unificação da Alemanha', p: 'Berlim (Versalhes)', d: 'O “sangue e ferro” de Bismarck — três guerras, um Reich, proclamado no Salão dos Espelhos.' },
  bismarck: { n: 'Otto von Bismarck', p: 'Berlim', d: 'O Chanceler de Ferro unifica a Alemanha por diplomacia e guerra, depois mantém a Europa em paz por 20 anos mantendo todos sob tensão.' },
  italian_unification: { n: 'Unificação da Itália', p: 'Roma', d: 'Os Mil de Garibaldi, o xadrez de Cavour e o sonho de Mazzini costuram sete estados em uma só Itália.' },
  edison: { n: 'A lâmpada de Edison', p: 'Menlo Park, EUA', d: '“Eu não falhei. Encontrei 10.000 maneiras que não funcionam” — a lâmpada incandescente e a indústria de inventar invenções.' },
  ems_ukaz: { n: 'O Ukaz de Ems proíbe a imprensa ucraniana', p: 'Império Russo', d: 'Alexandre II, de seu spa em Bad Ems, proíbe imprimir e importar livros ucranianos, partituras e até letras de canções no Império Russo — treze anos depois de o ministério do interior ter classificado o ucraniano como “uma língua que não existia”.' },
  tesla: { n: 'Nikola Tesla', p: 'Nova York', d: 'Corrente alternada, fundamentos do rádio, a bobina de Tesla — o mago cuja rede elétrica ilumina o mundo.' },
  franko: { n: 'Ivan Franko', p: 'Lviv, Ucrânia', d: 'Poeta, romancista, erudito, tradutor de uma dúzia de literaturas e organizador político a vida inteira — com Shevchenko, o segundo pilar do renascimento ucraniano.' },
  ukrainka: { n: 'Lesya Ukrainka', p: 'Volínia, Ucrânia', d: 'A grande poetisa e dramaturga da Ucrânia: “A Canção da Floresta” (1911) dá à literatura mundial a ninfa Mavka — escrita enquanto avançavam a tuberculose e a doença óssea que ensombraram toda a sua vida.' },
  ibsen: { n: 'Henrik Ibsen', p: 'Skien e Oslo, Noruega', d: 'Casa de Bonecas, Hedda Gabler, Peer Gynt — o pai do drama moderno põe no palco pessoas reais e verdades insuportáveis.' },
  munch: { n: 'Edvard Munch', p: 'Oslo, Noruega', d: 'O Grito (1893): a própria angústia torna-se ícone — “Eu pintei… o grito da natureza”, de um homem que nunca deixou de pintar o interior da mente.' },
  nansen: { n: 'Fridtjof Nansen', p: 'Oslo, Noruega', d: 'Explorador polar que deixou seu navio congelar no gelo de propósito — depois Alto Comissário para os Refugiados: o passaporte Nansen devolve o nome aos apátridas e ganha o Nobel da Paz de 1922.' },
  amundsen: { n: 'Roald Amundsen', p: 'Noruega', d: 'Primeiro pela Passagem do Noroeste (1903–06), primeiro no Polo Sul (14 de dezembro de 1911, cinco semanas antes de Scott), primeiro a sobrevoar o Polo Norte — desapareceu em 1928 ao voar para resgatar um rival.' },
  nobel: { n: 'Alfred Nobel', p: 'Estocolmo, Suécia', d: 'O inventor da dinamite gasta sua fortuna — todos os anos desde 1901 — recompensando quem “conferiu o maior benefício à humanidade”.' },
  kalevala: { n: 'Publicação do Kalevala', p: 'Helsinque/Carélia, Finlândia', d: 'Elias Lönnrot costura runas cantadas por bardos da Carélia no épico nacional finlandês — os mitos de Väinämöinen que ensinam a um povo que ele é um povo.' },
  curie: { n: 'Marie Curie', p: 'Paris', d: 'Dois Prêmios Nobel em duas ciências; ela cunha o termo “radioatividade” e carrega rádio nos bolsos até a morte.' },
  hrushevsky: { n: 'Mykhailo Hrushevsky', p: 'Kyiv', d: 'Sua “História da Ucrânia-Rus” em dez volumes devolveu a Rus de Kiev à história ucraniana — a resposta acadêmica à escola imperial que a havia anexado ao passado russo; em 1917 presidiu o primeiro parlamento ucraniano, a Rada Central, e morreu no exílio soviético.' },
  opium_war: { n: 'Primeira Guerra do Ópio', p: 'Cantão, China', d: 'A Grã-Bretanha luta para continuar vendendo ópio à China — e ganha Hong Kong e portos de tratado sob a mira dos canhões.' },
  taiping: { n: 'Rebelião Taiping', p: 'Nanjing, China', d: 'Um mestre-escola de aldeia que se dizia irmão mais novo de Cristo acende a guerra civil mais sangrenta da história — 20 milhões de mortos.' },
  suez: { n: 'Abertura do Canal de Suez', p: 'Suez, Egito', d: 'O Mediterrâneo encontra o Mar Vermelho: a rota marítima para a Índia encurta 8.900 km.' },
  nz_suffrage: { n: 'O voto feminino na Nova Zelândia', p: 'Nova Zelândia', d: 'A Nova Zelândia torna-se o primeiro país autogovernado em que as mulheres votam em eleições gerais — a petição de Kate Sheppard tem uma milha de comprimento.' },
  panama_canal: { n: 'Abertura do Canal do Panamá', p: 'Panamá', d: 'Um corte de 48 milhas pela selva, mais de 25.000 mortos por doença e desabamentos — o Atlântico e o Pacífico apertam as mãos.' },
  wright: { n: 'Primeiro voo motorizado', p: 'Kitty Hawk, EUA', d: '12 segundos, 36 metros — os irmãos Wright abrem a era da aviação numa praia ventosa da Carolina.' },
