  relativity: { n: 'Teoria da Relatividade', p: 'Berna e Berlim', d: '1905: relatividade especial e E=mc²; 1915: a gravidade como espaço-tempo curvo — os eclipses o provam certo em 1919.' },
  ww1: { n: 'Primeira Guerra Mundial', p: 'Sarajevo → mundo inteiro', d: 'As balas de um assassino em Sarajevo desfazem um século de impérios: 20 milhões de mortos, matança nas trincheiras e o mundo refeito.' },
  russian_rev: { n: 'Revolução Russa', p: 'Petrogrado', d: '“Paz, pão, terra” — os Romanov caem, os bolcheviques de Lenin tomam o poder: o primeiro estado socialista do mundo.' },
  unr: { n: 'Revolução Ucraniana de 1917–21', p: 'Kyiv', d: 'Do colapso de dois impérios emerge a República Popular Ucraniana — a Rada de Hrushevsky, Vynnychenko e Petliura declara independência em janeiro de 1918 e trava uma guerra de independência de cinco anos; derrotada, suas terras são repartidas entre a Rússia soviética, a Polônia, a Romênia e a Tchecoslováquia.' },
  estonia_1918: { n: 'A Estônia declara independência', p: 'Tallinn, Estônia', d: '24 de fevereiro de 1918: o Comitê de Salvação proclama a República; segue-se a Guerra de Independência — vitória sobre o Exército Vermelho em Võnnu em 1919, selada pela Paz de Tartu de 1920.' },
  latvia_1918: { n: 'A Letônia declara independência', p: 'Riga, Letônia', d: '18 de novembro de 1918, no teatro de Riga: um estado para um povo cujas terras foram disputadas por cruzados, poloneses, suecos e russos por 700 anos.' },
  lithuania_1918: { n: 'A Lituânia restaura a soberania', p: 'Vilnius, Lituânia', d: '16 de fevereiro de 1918: o Conselho da Lituânia aprova o Ato de Independência — o primeiro estado lituano moderno desde o Grão-Ducado; Vilnius é tomada pela Polônia em 1920 e Kaunas torna-se a “capital temporária”.' },
  finland_1917: { n: 'A Finlândia declara independência', p: 'Helsinque, Finlândia', d: '6 de dezembro de 1917: após 108 anos como Grão-Ducado russo — e 560 como metade oriental da Suécia — a Finlândia torna-se uma nação, e a Rússia de Lenin é a primeira a reconhecê-la.' },
  lenin: { n: 'Vladimir Lenin', p: 'Petrogrado', d: 'Revolucionário profissional no exílio, depois chefe de estado — conduz o golpe bolchevique e funda a URSS.' },
  spanish_flu: { n: 'Pandemia de gripe espanhola', p: 'Mundo inteiro', d: 'Infectou um terço da humanidade e matou mais pessoas (50–100 milhões) que a Grande Guerra — sobretudo adultos jovens.' },
  versailles: { n: 'Tratado de Versalhes', p: 'Versalhes', d: 'A Alemanha é culpada, desarmada e cobrada em 132 bilhões de marcos-ouro — “um armistício por vinte anos”, prevê Foch.' },
  depression: { n: 'Grande Depressão', p: 'Nova York', d: 'Wall Street despenca e leva o mundo junto: 25% de desemprego, bancos quebrados — e ditaduras em ascensão.' },
  holodomor: { n: 'Holodomor', p: 'Ucrânia', d: 'As cotas de requisição, as listas negras e as deportações de Stalin esvaziam de grão as aldeias ucranianas enquanto o estado o exporta; a fome mata milhões — a literatura acadêmica mais comumente cita de 3,5 a 5 milhões. A Ucrânia e muitos outros estados o reconhecem como genocídio.' },
  executed_renaissance: { n: 'O Renascimento Executado', p: 'Kharkiv e Kyiv', d: 'A deslumbrante geração ucraniana dos anos 1920 — a prosa de Khvylovy, o teatro Berezil de Kurbas, o neoclassicismo de Zerov — é aniquilada por prisões em massa; em novembro de 1937, centenas de escritores, eruditos e artistas da república são fuzilados na clareira de Sandarmokh.' },
  ww2: { n: 'Segunda Guerra Mundial', p: 'Mundo inteiro', d: 'O conflito mais letal da história: 70–85 milhões de mortos, o Holocausto e a ordem mundial reconstruída a partir das cinzas.' },
  soviet_baltic_occupation: { n: 'Ocupação soviética dos países bálticos', p: 'Estônia · Letônia · Lituânia', d: 'Protocolo secreto, ultimato, anexação (1940); dezenas de milhares deportados para a Sibéria em vagões de gado em 1941 e 1949; os Irmãos da Floresta seguem combatendo nas matas pelos anos 1950. A ocupação dura até 1991.' },
  winter_war: { n: 'Guerra de Inverno', p: 'Istmo da Carélia, Finlândia', d: 'Stalin envia 450.000 homens contra a Finlândia no inverno ártico — e os finlandeses, em esquis e com coquetéis Molotov, resistem por 105 dias; cederam território, mas nunca foram conquistados.' },
  holocaust: { n: 'O Holocausto', p: 'Europa ocupada', d: 'A Alemanha nazista industrializa o genocídio: seis milhões de judeus, além de ciganos, eslavos, prisioneiros políticos e outros, assassinados.' },
  wallenberg: { n: 'Raoul Wallenberg', p: 'Budapeste, Hungria', d: 'O diplomata sueco que entregou a dezenas de milhares de judeus húngaros passaportes protetores e casas seguras — depois foi capturado pelos soviéticos em 1945 e desapareceu na Lubyanka; dado como morto em 1947.' },
  dday: { n: 'Dia D', p: 'Normandia, França', d: 'A maior invasão anfíbia da história — 156.000 soldados aliados desembarcam na França e iniciam a libertação da Europa Ocidental.' },
  babi_yar: { n: 'Massacre de Babi Yar', p: 'Kyiv', d: 'Em 29–30 de setembro de 1941, o Einsatzgruppe C das SS fuzila 33.771 judeus de Kyiv na ravina de Babi Yar — um dos maiores massacres isolados do Holocausto; ao longo da ocupação, dezenas de milhares mais são mortos ali.' },
  upa: { n: 'Exército Insurgente Ucraniano (UPA)', p: 'Ucrânia ocidental', d: 'Exército de guerrilha que lutou por um estado ucraniano independente contra as forças soviéticas e alemãs — e que foi implicado na limpeza étnica de civis poloneses na Volínia (1943–44), tema que ainda pesa na memória polaco-ucraniana. A caçada soviética durou até os anos 1950.' },
