  mlk_speech: { n: '“Eu Tenho um Sonho”', p: 'Washington, D.C.', d: 'Um quarto de milhão de pessoas marcha sobre Washington; dos degraus do Lincoln Memorial, o sonho de King entra na história.' },
  mlk: { n: 'Martin Luther King Jr.', p: 'Atlanta, EUA', d: 'A não violência como estratégia e sermão — a voz premiada com o Nobel do movimento dos Direitos Civis, assassinado aos 39 anos.' },
  vietnam_war: { n: 'Guerra do Vietnã', p: 'Vietnã', d: 'Vinte anos de guerra terminam com helicópteros decolando do telhado da embaixada de Saigon — a primeira guerra perdida na televisão.' },
  apollo11: { n: 'Apollo 11 pousa na Lua', p: 'Cabo Canaveral → Lua', d: '“A Águia pousou.” Armstrong e Aldrin caminham em outro mundo diante de 600 milhões de espectadores — “um salto gigante para a humanidade”.' },
  berlin_wall: { n: 'Queda do Muro de Berlim', p: 'Berlim', d: 'Uma coletiva de imprensa fracassada, depois martelos: o Muro se abre, e o mais concreto símbolo da Guerra Fria desmorona.' },
  singing_revolution: { n: 'Revolução Cantada e Caminho Báltico', p: 'Tallinn → Riga → Vilnius', d: 'Centenas de milhares cantam em uníssono canções proibidas — e em 23 de agosto de 1989 dois milhões de pessoas dão as mãos ao longo de 675 km, de Tallinn a Vilnius. A Lituânia declara a restauração primeiro (11 de março de 1990); em agosto de 1991, as três estão livres.' },
  www: { n: 'Invenção da World Wide Web', p: 'CERN, Genebra', d: 'Tim Berners-Lee entrega HTML, HTTP e o primeiro navegador — e depois distribui tudo de graça.' },
  soviet_collapse: { n: 'Dissolução da URSS', p: 'Moscou', d: 'Quinze repúblicas, uma bandeira arriada: a União Soviética termina no dia de Natal de 1991 — e com ela a Guerra Fria.' },
  ukraine_independence: { n: 'A Ucrânia declara independência', p: 'Kyiv', d: 'Em 24 de agosto de 1991, após o colapso do golpe em Moscou, a Verkhovna Rada declara a independência; em 1º de dezembro, mais de 90% dos eleitores — com maioria em todas as regiões — a confirmam em referendo.' },
  maidan: { n: 'Euromaidan / Revolução da Dignidade', p: 'Kyiv', d: 'Protestos de massa explodem quando o governo suspende o Acordo de Associação com a UE; após três meses, atiradores matam cerca de uma centena de manifestantes (os Cem Celestiais) e o presidente foge — a Rússia responde anexando a Crimeia e acendendo a guerra no Donbas.' },
  stus: { n: 'Vasyl Stus', p: 'Região de Vinnitsa, Ucrânia', d: 'Poeta e tradutor que se recusou a abjurar: 23 anos da vida passados em prisões, campos e exílio, morrendo em greve de fome no Perm-36 em 1985 — reabilitado postumamente e sepultado novamente como figura nacional.' },
  ukraine_war: { n: 'Guerra russo-ucraniana', p: 'Ucrânia', d: 'Iniciada com a anexação da Crimeia e a guerra encoberta no Donbas (2014), a Rússia lança a invasão em larga escala da Ucrânia em 24 de fevereiro de 2022 — a maior guerra na Europa desde 1945. Kyiv resiste, e a guerra redesenha a ordem mundial.' },
  mandela_elected: { n: 'Mandela eleito presidente', p: 'Pretória', d: 'Após 27 anos preso, Nelson Mandela é eleito na primeira votação livre da África do Sul — e perdoa seus carcereiros.' },
