  se_magnus_stark: { n: 'Magnus, o Forte', p: 'Skara, Suécia', d: 'Neto nascido na Dinamarca de Sigurd, o Cruzado — primeiro pretendente sueco com sangue real norueguês; caiu em Fotevik (1134).' },
  se_sverker_aldre: { n: 'Sverker I, o Velho', p: 'Linköping, Suécia', d: 'Primeiro da linhagem Sverker da Östergötland: fundou a abadia de Alvastra — assassinado pelo próprio criado a caminho da missa (1156).' },
  se_erik_helige: { n: 'Erik IX, o Santo', p: 'Uppsala, Suécia', d: 'Liderou a cruzada à Finlândia com o bispo Henrique — assassinado na missa da Ascensão de Uppsala; santo padroeiro da Suécia.' },
