  se_johan_sverkersson: { n: 'Johan I Sverkersson', p: 'Uppsala, Suécia', d: 'Último da linhagem Sverker: liderou aos vinte uma cruzada condenada à Estônia, morto aos vinte e um.' },
  se_erik_xi: { n: 'Erik XI, o Gago e Coxo', p: 'Uppsala, Suécia', d: 'Duas vezes coroado, duas vezes exilado — o tranquilo último rei da linhagem Erik.' },
