  se_karl_x_gustav: { n: 'Karl X Gustav', p: 'Estocolmo', d: 'Marchou com um exército sobre os Beltes congelados até Copenhague (1658) — a Suécia no seu máximo, a Dinamarca partida pelo tratado.' },
