  se_gustav_iv_adolf: { n: 'Gustavo IV Adolfo', p: 'Estocolmo', d: 'O idealista teimoso: perdeu a Finlândia para a Rússia (1809) e o trono no golpe do mesmo ano.' },
  se_karl_xiii: { n: 'Karl XIII', p: 'Estocolmo', d: 'O velho rei sem filhos que adotou um marechal francês — a linhagem Bernadotte reina ainda.' },
  se_karl_xiv_johan: { n: 'Karl XIV Johan (Bernadotte)', p: 'Estocolmo', d: 'Marechal napoleônico — príncipe herdeiro — rei: mudou de lado, tomou a Noruega em 1814, fundou a dinastia.' },
  se_oskar_i: { n: 'Óscar I', p: 'Estocolmo', d: 'O Bernadotte brando: liberalizou a união, construiu a primeira ferrovia sueca, ficou fora da guerra da Crimeia.' },
