  se_gustaf_vi_adolf: { n: 'Gustaf VI Adolf', p: 'Estocolmo', d: 'O rei arqueólogo: escavações etruscas e propriedade constitucional através de três décadas de reformas.' },
  se_carl_xvi_gustaf: { n: 'Carl XVI Gustaf', p: 'Estocolmo', d: 'Rei desde 1973 — chefe de Estado cerimonial sob a constituição de 1974, a moderna figura de avô dos Bernadotte.' }
