  de_carloman_bavaria: { n: 'Carlomano da Baviera', p: 'Ratisbona, Alemanha', d: 'Filho mais velho de Luís o Germânico: a Baviera por herança, a Itália e a coroa imperial por conquista — um derrame corta tudo em quatro anos.' },
